import {createChatOrchestrator} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});

const session = (): ChatSession => ({
  sessionId: 'test-session',
  userId: 'user-1',
  entries: [{role: 'user', content: 'hello', timestamp: new Date().toISOString()}],
});

const rejectingWith = (reason: unknown): AIProvider => ({
  // eslint-disable-next-line require-yield
  async *sendMessage(): AsyncGenerator<MessageChunk> {
    throw reason;
  },
  async generateStructured<T>(): Promise<T> {
    return {} as T;
  },
});

const seenByOnError = async (reason: unknown) => {
  const seen: Error[] = [];
  const orchestrator = createChatOrchestrator(rejectingWith(reason), promptBuilder, undefined, {
    hooks: {
      onError: async (_s, error) => {
        seen.push(error);
      },
    },
  });
  await orchestrator.processMessage(session()).catch(() => undefined);
  return seen;
};

describe('ChatOrchestrator onError wrapping', () => {
  it.each([['a string', 'string boom'], ['undefined', undefined], ['a plain object', {code: 503}]])(
    'wraps %s in one Error whose cause is the original value',
    async (_label, reason) => {
      const seen = await seenByOnError(reason);

      expect(seen).toHaveLength(1);
      expect(seen[0]).toBeInstanceOf(Error);
      expect(seen[0].cause).toBe(reason);
    }
  );

  it('passes an Error through as the same instance', async () => {
    const reason = new Error('boom');

    const seen = await seenByOnError(reason);

    expect(seen).toEqual([reason]);
    expect(seen[0]).toBe(reason);
  });
});
